	if req.Previous != nil {
		q.Add("previous", fmt.Sprintf("%v", *req.Previous))
	}
	if req.Filter != nil {
		q.Add("filter", fmt.Sprintf("%v", *req.Filter))
	}
	if req.Pod != nil {
		q.Add("pod", fmt.Sprintf("%v", *req.Pod))
	}
	gwReq.SetQueryParamsFromValues(q)
